class Solution:
    def kConcatenationMaxSum(self, arr: List[int], k: int) -> int:
        MOD = 10**9 + 7
        n = len(arr)
        b = arr * (2 if k > 1 else 1)
        cur = best = 0
        for x in b:
            cur = max(cur + x, x)
            best = max(best, cur)
        if k > 2 and sum(arr) > 0:
            best += sum(arr) * (k - 2)
        return best % MOD

