class Solution {
public:
    int kConcatenationMaxSum(vector<int>& arr, int k) {
        const long long MOD = 1000000007LL;
        long long n = arr.size();
        vector<int> b;
        int reps = k > 1 ? 2 : 1;
        for (int r = 0; r < reps; r++) b.insert(b.end(), arr.begin(), arr.end());
        long long cur = 0, best = 0;
        for (int x : b) { cur = max(cur + (long long)x, (long long)x); best = max(best, cur); }
        long long tot = accumulate(arr.begin(), arr.end(), 0LL);
        if (k > 2 && tot > 0) best += tot * (long long)(k - 2);
        return (int)(best % MOD);
    }
};

