var kConcatenationMaxSum = function(arr, k) {
    const MOD = 1000000007;
    let b = k > 1 ? arr.concat(arr) : arr.slice();
    let cur = 0, best = 0;
    for (const x of b) { cur = Math.max(cur + x, x); best = Math.max(best, cur); }
    let tot = arr.reduce((a, x) => a + x, 0);
    if (k > 2 && tot > 0) best += tot * (k - 2);
    return ((best % MOD) + MOD) % MOD;
};

